146	
147	func runBatchRegister(args []string, stdout io.Writer) error {
148		fs := flag.NewFlagSet("batch-register", flag.ContinueOnError)
149		fs.SetOutput(io.Discard)
150		registryPath := fs.String("registry", "", "registry `file` to read and write")
151		batchRaw := fs.String("batch", "", "batch number (unique within the registry)")
152		productRaw := fs.String("product", "", "product number")
153		quantityRaw := fs.String("quantity", "", "positive decimal integer quantity")
154		unitRaw := fs.String("unit", "", "measurement unit")
155		if err := fs.Parse(args); err != nil {
156			if errors.Is(err, flag.ErrHelp) {
157				fmt.Fprint(stdout, rootUsage())
158				return nil
159			}
160			return &usageError{msg: "batch-register: " + err.Error(), usage: batchRegisterUsage}
161		}
162		if fs.NArg() != 0 {
163			return &usageError{
164				msg:   fmt.Sprintf("batch-register: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
165				usage: batchRegisterUsage,
166			}
167		}
168	
169		// Missing or malformed input must never create or modify the registry
170		// file, so required flags are checked before reading or writing anything.
171		required := []struct {
172			name  string
173			value string
174		}{
175			{"--registry", *registryPath},
176			{"--batch", *batchRaw},
177			{"--product", *productRaw},
178			{"--quantity", *quantityRaw},
179			{"--unit", *unitRaw},
180		}
181		var missing []string
182		for _, f := range required {
183			if f.value == "" {
184				missing = append(missing, f.name)
185			}
186		}
187		if len(missing) > 0 {
188			return &usageError{
189				msg:   "batch-register: missing required flag(s): " + strings.Join(missing, ", "),
190				usage: batchRegisterUsage,
191			}
192		}
193	
194		batch, err := batchreg.NormalizeField(*batchRaw)
195		if err != nil {
196			return &usageError{msg: "batch-register: invalid --batch: " + err.Error(), usage: batchRegisterUsage}
197		}
198		product, err := batchreg.NormalizeField(*productRaw)
199		if err != nil {
200			return &usageError{msg: "batch-register: invalid --product: " + err.Error(), usage: batchRegisterUsage}
201		}
202		unit, err := batchreg.NormalizeField(*unitRaw)
203		if err != nil {
204			return &usageError{msg: "batch-register: invalid --unit: " + err.Error(), usage: batchRegisterUsage}
205		}
206		quantity, err := batchreg.ParseQuantity(*quantityRaw)
207		if err != nil {
208			return &usageError{msg: "batch-register: invalid --quantity: " + err.Error(), usage: batchRegisterUsage}
209		}
210	
211		reg, existed, err := batchreg.Load(*registryPath)
212		if err != nil {
213			return err
214		}
215		outcome, err := batchreg.Register(reg, batchreg.Input{
216			Batch: batch, Product: product, Quantity: quantity, Unit: unit,
217		})
218		if err != nil {
219			return err
220		}
221		if outcome.Created {
222			if err := batchreg.Save(*registryPath, reg); err != nil {
223				if !existed {
224					// Nothing was registered before; drop any partial new file.
225					os.Remove(*registryPath)
226				}
227				return err
228			}
229		}
230	
231		status := "duplicate"
232		if outcome.Created {
233			status = "created"
234		}
235		result := struct {
236			Batch    string `json:"batch"`
237			Product  string `json:"product"`
238			Quantity int64  `json:"quantity"`
239			Unit     string `json:"unit"`
240			Status   string `json:"status"`
241		}{
242			Batch:    outcome.Batch.Batch,
243			Product:  outcome.Batch.Product,
244			Quantity: outcome.Batch.Quantity,
245			Unit:     outcome.Batch.Unit,
246			Status:   status,
247		}
248		payload, err := json.Marshal(result)
249		if err != nil {
250			return err
251		}
252		_, err = fmt.Fprintln(stdout, string(payload))
253		return err
254	}
