256	func runBatchImport(args []string, stdout io.Writer) error {
257		fs := flag.NewFlagSet("batch-import", flag.ContinueOnError)
258		fs.SetOutput(io.Discard)
259		registryPath := fs.String("registry", "", "registry `file` to read and write")
260		inputPath := fs.String("input", "", "read-only JSON manifest `file` to import")
261		if err := fs.Parse(args); err != nil {
262			if errors.Is(err, flag.ErrHelp) {
263				fmt.Fprint(stdout, rootUsage())
264				return nil
265			}
266			return &usageError{msg: "batch-import: " + err.Error(), usage: batchImportUsage}
267		}
268		if fs.NArg() != 0 {
269			return &usageError{
270				msg:   fmt.Sprintf("batch-import: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
271				usage: batchImportUsage,
272			}
273		}
274		if *registryPath == "" || *inputPath == "" {
275			var missing []string
276			if *registryPath == "" {
277				missing = append(missing, "--registry")
278			}
279			if *inputPath == "" {
280				missing = append(missing, "--input")
281			}
282			return &usageError{
283				msg:   "batch-import: missing required flag(s): " + strings.Join(missing, ", "),
284				usage: batchImportUsage,
285			}
286		}
287	
288		// The manifest is read-only and is parsed (and fully validated) before
289		// the registry is loaded or written, so bad input cannot touch it.
290		data, err := os.ReadFile(*inputPath)
291		if err != nil {
292			return fmt.Errorf("batch-import: cannot read input file %q: %w", *inputPath, err)
293		}
294		inputs, err := batchreg.ParseManifest(data)
295		if err != nil {
296			return fmt.Errorf("batch-import: invalid input file %q: %w", *inputPath, err)
297		}
298	
299		reg, existed, err := batchreg.Load(*registryPath)
300		if err != nil {
301			return fmt.Errorf("batch-import: %w", err)
302		}
303		outcomes, err := batchreg.Import(reg, inputs)
304		if err != nil {
305			return fmt.Errorf("batch-import: %w", err)
306		}
307	
308		type importResultJSON struct {
309			Batch    string `json:"batch"`
310			Product  string `json:"product"`
311			Quantity int64  `json:"quantity"`
312			Unit     string `json:"unit"`
313			Status   string `json:"status"`
314		}
315		results := make([]importResultJSON, len(outcomes))
316		anyCreated := false
317		for i, o := range outcomes {
318			status := "duplicate"
319			if o.Created {
320				status = "created"
321				anyCreated = true
322			}
323			results[i] = importResultJSON{
324				Batch:    o.Batch.Batch,
325				Product:  o.Batch.Product,
326				Quantity: o.Batch.Quantity,
327				Unit:     o.Batch.Unit,
328				Status:   status,
329			}
330		}
331	
332		// An all-duplicate manifest must leave bytes and mtime untouched, so the
333		// registry is written only when at least one record was newly created.
334		if anyCreated {
335			if err := batchreg.Save(*registryPath, reg); err != nil {
336				if !existed {
337					// The registry never existed before this import; drop any
338					// partial new file so a failed save leaves nothing behind.
339					os.Remove(*registryPath)
340				}
341				return fmt.Errorf("batch-import: %w", err)
342			}
343		}
344	
345		payload, err := json.Marshal(struct {
346			Results []importResultJSON `json:"results"`
347		}{Results: results})
348		if err != nil {
349			return fmt.Errorf("batch-import: %w", err)
350		}
351		_, err = fmt.Fprintln(stdout, string(payload))
352		if err != nil {
353			return fmt.Errorf("batch-import: %w", err)
354		}
355		return nil
356	}
357	
358	func runDemo() {
359		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
360			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
361		if err := govflow.Vote(&proposal, 700, true); err != nil {
362			fmt.Println("vote refused:", err)
363		}
364		if err := govflow.Vote(&proposal, 200, false); err != nil {
365			fmt.Println("vote refused:", err)
366		}
367		next := govflow.Tally(&proposal)
368		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
369		proposal.State = next
370		proposal.TimelockEnd = 400
371		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
372	}
373

