597		reg := &Registry{Version: FormatVersion}
598		_, err := Import(reg, []Input{
599			{Batch: "B1", Product: "P", Quantity: 1, Unit: "kg"},
600			{Batch: "B2", Product: "P", Quantity: 1, Unit: "kg"},
601			{Batch: "B1", Product: "P", Quantity: 2, Unit: "kg"},
602		})
603		var ce *ManifestConflictError
604		if !errors.As(err, &ce) {
605			t.Fatalf("expected ManifestConflictError, got %v", err)
606		}
607		if ce.Position != 3 || ce.Batch != "B1" || ce.Source != "manifest" || ce.PrevPos != 1 {
608			t.Fatalf("unexpected conflict: %+v", ce)
609		}
610		if len(ce.Fields) != 1 || ce.Fields[0] != "quantity" {
611			t.Fatalf("fields = %v", ce.Fields)
612		}
613		if len(reg.Batches) != 0 {
614			t.Fatalf("rejected manifest left new batches: %+v", reg.Batches)
615		}
616	}
617	
618	func TestImportConflictNamesAllFields(t *testing.T) {
619		reg := &Registry{Version: FormatVersion, Batches: []Batch{
620			{Batch: "B1", Product: "P", Quantity: 1, Unit: "kg"},
621		}}
622		_, err := Import(reg, []Input{{Batch: "B1", Product: "Q", Quantity: 2, Unit: "g"}})
623		var ce *ManifestConflictError
