// ErrInvalidUTF8 reports that a batch, product or unit value carries bytes
// that are not valid UTF-8 (or a JSON string escape that does not encode a
// Unicode scalar, such as a lone surrogate). Go's JSON decoder otherwise
// rewrites such input to the replacement character U+FFFD, which would merge
// distinct inputs into one value; the value is rejected instead. A genuine,
// deliberately typed U+FFFD is valid and never triggers this error.
var ErrInvalidUTF8 = errors.New("value is not valid UTF-8 text")

// EncodingError reports an invalid encoding in one of the three text fields.
// Field is one of "batch", "product" and "unit". It is returned directly for
// command-line values and is wrapped by a FormatError or ManifestRecordError
// when reading a file, so the record position stays attached.
type EncodingError struct {
	Field string
}

func (e *EncodingError) Error() string {
	return fmt.Sprintf("field %q is not valid UTF-8 text and must not be replaced with %q", e.Field, "�")
}

// validateUTF8 rejects invalid encoding without ever decoding the string, so
// the rejected bytes cannot be mistaken for a replacement character.
func validateUTF8(field, value string) error {
	if !utf8.ValidString(value) {
		return &EncodingError{Field: field}
	}
	return nil
}

// jsonStringTokenValid reports whether raw is a syntactically complete JSON
// string literal whose decoded text is a valid Unicode string. It inspects
// the raw token only: malformed bytes fail as JSON, and a \u escape denoting
// a lone surrogate fails as invalid encoding, while a surrogate pair and the
// escape "�" stay valid. Raw invalid UTF-8 bytes (other than those a
// JSON string is allowed to carry literally, which are none) fail as well.
func jsonStringTokenValid(raw []byte) bool {
	return jsonStringTokenError(raw) == nil
}

// jsonStringTokenError validates one JSON string token, returning a
// json.SyntaxError for malformed JSON and ErrInvalidUTF8 for a decoded string
// that is not valid Unicode.
func jsonStringTokenError(raw []byte) error {
	if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
		return jsonSyntaxError(raw)
	}
	// Scan the literal body between the quotes, honoring escapes.
	for i := 1; i < len(raw)-1; {
		b := raw[i]
		if b == '"' {
			return jsonSyntaxError(raw) // unescaped quote ends the token early
		}
		if b == '\\' {
			if i+1 >= len(raw)-1 {
				return jsonSyntaxError(raw)
			}
			switch raw[i+1] {
			case '"', '\\', '/', 'b', 'f', 'n', 'r', 't':
				i += 2
				continue
			case 'u':
				r, size, ok := readUEScape(raw[i+2 : len(raw)-1])
				if !ok {
					return jsonSyntaxError(raw)
				}
				// A lone surrogate never denotes a Unicode scalar. A paired
				// surrogate (\uD800-\uDBFF immediately followed by a
				// \uDC00-\uDFFF) is consumed together and is valid.
				if utf16.IsSurrogate(r) {
					if r2, size2, ok2 := readUEScape(raw[i+2+size : len(raw)-1]); ok2 &&
						r2 >= 0xDC00 && r2 <= 0xDFFF {
						i += 2 + size + 2 + size2
						continue
					}
					return ErrInvalidUTF8
				}
				i += 2 + size
				continue
			default:
				return jsonSyntaxError(raw)
			}
		}
		if b < 0x20 {
			return jsonSyntaxError(raw) // control characters must be escaped
		}
		// A literal byte >= 0x80 starts a UTF-8 sequence; verify it decodes
		// to a rune (RuneError with width 1 means an invalid byte).
		if b >= 0x80 {
			r, size := utf8.DecodeRune(raw[i : len(raw)-1])
			if r == utf8.RuneError && size == 1 {
				return ErrInvalidUTF8
			}
			i += size
			continue
		}
		i++
	}
	return nil
}

// readUEScape reads four hex digits at the start of p, returning the code
// unit, the number of bytes consumed (4 on success) and whether it parsed.
func readUEScape(p []byte) (r rune, size int, ok bool) {
	if len(p) < 4 {
		return 0, 0, false
	}
	var v rune
	for i := 0; i < 4; i++ {
		c := p[i]
		var d rune
		switch {
		case c >= '0' && c <= '9':
			d = rune(c - '0')
		case c >= 'a' && c <= 'f':
			d = rune(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = rune(c-'A') + 10
		default:
			return 0, 0, false
		}
		v = v<<4 | d
	}
	return v, 4, true
}

// jsonSyntaxError builds a JSON syntax error shaped like encoding/json's.
func jsonSyntaxError(raw []byte) error {
	return &json.SyntaxError{Msg: "invalid JSON string literal", Offset: int64(len(raw))}
}

